import{_ as t,o as n,c as a,a3 as i}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse(`{"title":"Installation de Zendure pour HA","description":"Installation et configuration de l'intégration Zendure pour Home Assistant.","frontmatter":{"title":"Installation de Zendure pour HA","description":"Installation et configuration de l'intégration Zendure pour Home Assistant."},"headers":[],"relativePath":"fr/collection/zendure-ha/installation.md","filePath":"fr/collection/zendure-ha/installation.md","lastUpdated":1793123358000}`),o={name:"fr/collection/zendure-ha/installation.md"};function r(s,e,d,l,c,u){return n(),a("div",null,[...e[0]||(e[0]=[i('<p><a id="zendure-ha-installation"></a><a id="orientation-actuelle"></a></p><h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation {#installation}&quot;">​</a></h1><h2 id="installation-uber-hacs" tabindex="-1">Installation via HACS <a class="header-anchor" href="#installation-uber-hacs" aria-label="Permalink to &quot;Installation via HACS {#installation-uber-hacs}&quot;">​</a></h2><ol><li>Ouvrir Home Assistant.</li><li>Ouvrir <code>HACS</code>.</li><li>Accéder à <code>Integrationen</code>. 4. Ouvrir <code>+ Explore &amp; Download Repos</code>.</li><li>Rechercher <code>Zendure</code>.</li><li>Télécharger <code>Zendure Home Assistant Integration</code>.</li><li>Actualiser le navigateur si Home Assistant n&#39;affiche pas encore directement l&#39;intégration.</li><li>Ouvrir <code>Einstellungen -&gt; Geräte &amp; Dienste -&gt; Integration hinzufügen</code>.</li><li>Rechercher <code>Zendure</code> et lancer la configuration.</li></ol><p>Lien direct :</p><p><a href="https://my.home-assistant.io/redirect/config_flow_start/?domain=zendure_ha" target="_blank" rel="noreferrer">Ajouter l&#39;intégration Zendure dans Home Assistant</a></p><h2 id="zendure-app-token" tabindex="-1">Jeton (token) de l&#39;application Zendure <a class="header-anchor" href="#zendure-app-token" aria-label="Permalink to &quot;Jeton (token) de l&#39;application Zendure {#zendure-app-token}&quot;">​</a></h2><p>L&#39;intégration utilise un jeton provenant de l&#39;application Zendure. Ce jeton doit être issu du compte principal sur lequel les appareils sont enregistrés.</p><div class="warning custom-block"><p class="custom-block-title">Mise à niveau depuis des versions antérieures</p><p>Pour les installations anciennes comportant un second compte ou utilisant une ancienne méthode de connexion, l&#39;ancienne configuration doit être supprimée puis recréée. L&#39;intégration actuelle repose sur un système de jetons (tokens).</p></div><p>La fenêtre de saisie du jeton est documentée dans le wiki d&#39;origine, capture d&#39;écran à l&#39;appui :</p><p><a href="https://github.com/Zendure/Zendure-HA/wiki/Installation" target="_blank" rel="noreferrer">Capture d&#39;écran du jeton dans le wiki d&#39;origine</a></p><h2 id="optionen-im-einrichtungsdialog" tabindex="-1">Options dans la fenêtre de configuration <a class="header-anchor" href="#optionen-im-einrichtungsdialog" aria-label="Permalink to &quot;Options dans la fenêtre de configuration {#optionen-im-einrichtungsdialog}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Signification</th></tr></thead><tbody><tr><td><code>Zendure Token</code></td><td>Jeton (token) provenant de l&#39;application Zendure</td></tr><tr><td><code>P1 Sensor für Smart Matching</code></td><td>Capteur de consommation domestique : valeur positive en cas de consommation, négative en cas d&#39;injection sur le réseau</td></tr><tr><td><code>MQTT-Kommunikation loggen</code></td><td>Enregistre les échanges MQTT dans les journaux (logs) de Home Assistant (si le mode débogage est activé)</td></tr><tr><td><code>Lokales MQTT verwenden</code></td><td>Ouvre une seconde fenêtre pour la saisie des données MQTT locales</td></tr><tr><td><code>MQTT-Benutzer automatisch verwalten</code></td><td>Tente de gérer automatiquement les identifiants d&#39;accès MQTT</td></tr><tr><td><code>WLAN SSID</code></td><td>Nom du réseau Wi-Fi pour la reconfiguration des appareils</td></tr><tr><td><code>Wifi Passwort</code></td><td>Mot de passe du réseau Wi-Fi pour la reconfiguration des appareils</td></tr></tbody></table><h2 id="nach-der-einrichtung" tabindex="-1">Après la configuration <a class="header-anchor" href="#nach-der-einrichtung" aria-label="Permalink to &quot;Après la configuration {#nach-der-einrichtung}&quot;">​</a></h2><p>Une fois la configuration effectuée avec succès, les appareils Zendure et leurs entités apparaissent dans Home Assistant. Si vous possédez plusieurs appareils, il est recommandé de configurer correctement le <a href="/fr/collection/zendure-ha/fuse-group">groupe de protection (Fuse Group)</a> afin que les fonctionnalités de « Smart-Matching » (correspondance intelligente) et de limitation de puissance fonctionnent de manière optimale.</p>',15)])])}const m=t(o,[["render",r]]);export{h as __pageData,m as default};
